**Describe the bug**
zstd.h says the value returned by ZSTD_decompressStream() "is a suggested next input size (just a hint for better latency)", and lib/README.md describes legacy-format decoding as "a transparent capability triggered within decompression functions". With legacy support compiled in, a valid v0.5/v0.6/v0.7 frame decodes with ZSTD_decompress() and with ZSTD_decompressStream() when the first call carries at least 5 bytes, but ZSTD_decompressStream() returns `Unknown frame descriptor` when the first call carries only 1–4 bytes. Reproduced on v1.5.7 (f8745da6) and on dev 01b7154f (2026-09-18) built with ZSTD_LEGACY_SUPPORT=5.

**To Reproduce**
repro.c:
```
/* Feeds one zstd frame to ZSTD_decompressStream() in two pieces (first k bytes, then the rest)
 * and compares the outcome with feeding it whole. Public API only.
 * zstd.h: the return value of ZSTD_decompressStream() is "a suggested next input size (just a
 * hint for better latency)", so how the caller chunks the input must not change the result.
 *   build: cc -I<zstd>/lib repro.c <zstd>/lib/libzstd.a -o repro
 *   usage: ./repro frame.zst      exit 0 = every split agrees with the whole-input result */
#include <stdio.h>
#include <stdlib.h>
#include <zstd.h>

/* returns 1 and sets *total on success, 0 and sets *err on failure */
static int decode(const unsigned char* src, size_t n, size_t k, size_t* total, const char** err, size_t* fed_out)
{
    ZSTD_DStream* zds = ZSTD_createDStream();
    size_t cap = ZSTD_DStreamOutSize(), fed = 0;
    unsigned char* dst = malloc(cap);
    int calls = 0, ok = 0;
    *total = 0; *err = NULL;
    ZSTD_initDStream(zds);
    for (;;) {
        ZSTD_inBuffer in = { src + fed, (calls == 0 && k < n) ? k : n - fed, 0 };
        ZSTD_outBuffer out = { dst, cap, 0 };
        size_t ret = ZSTD_decompressStream(zds, &out, &in);
        calls++; fed += in.pos; *total += out.pos;
        if (ZSTD_isError(ret)) { *err = ZSTD_getErrorName(ret); break; }
        if (ret == 0) { ok = 1; break; }                 /* frame complete and flushed */
        if (in.pos == 0 && out.pos == 0) { *err = "stalled: no progress (truncated input?)"; break; }
    }
    *fed_out = fed;
    free(dst); ZSTD_freeDStream(zds);
    return ok;
}

int main(int argc, char** argv)
{
    unsigned char* buf = malloc(1 << 20);
    FILE* f = argc > 1 ? fopen(argv[1], "rb") : NULL;
    size_t n, total, fed, whole_total; const char* err; int bad = 0;
    if (!f) { fprintf(stderr, "usage: %s frame.zst\n", argv[0]); return 2; }
    n = fread(buf, 1, 1 << 20, f); fclose(f);
    printf("zstd %s, %zu-byte input, magic %02x %02x %02x %02x\n", ZSTD_versionString(), n, buf[0], buf[1], buf[2], buf[3]);
    int whole = decode(buf, n, n, &whole_total, &err, &fed);
    if (whole) printf("  whole input : OK, %zu bytes out\n", whole_total);
    else       printf("  whole input : ERROR %s\n", err);
    for (size_t k = 1; k <= 8 && k < n; k++) {
        int ok = decode(buf, n, k, &total, &err, &fed);
        if (ok) printf("  first call %zu byte%s: OK, %zu bytes out\n", k, k == 1 ? " " : "s", total);
        else    printf("  first call %zu byte%s: ERROR %s (consumed %zu/%zu)\n", k, k == 1 ? " " : "s", err, fed, n);
        if (ok != whole || (ok && total != whole_total)) bad = 1;
    }
    printf(bad ? "  => MISMATCH: outcome depends on how the input was split\n" : "  => consistent\n");
    return bad;
}
```
