  [PetMood.HAPPY]: "😺",
  [PetMood.EXCITED]: "😸",
  [PetMood.CONTENT]: "😼",
  [PetMood.SAD]: "😿",
  [PetMood.TIRED]: "😽",
  [PetMood.SICK]: "🙀",
  [PetMood.HUNGRY]: "😾"
}

