body_text:
### Go version

go1.27.0 (linux/arm64, darwin/arm64). The code is the same on master as of 2026-10-03.

### What did you do?

Served long-lived HTTP/2 requests and let clients disappear without resetting their streams (the client's socket is closed while a request is open). Attached is a reproducer that uses only the standard library: one streaming request, the client's socket closed under it, the server kept running. It tracks the server's and the client's `net.Conn` with `runtime.AddCleanup` and reports how long each stayed reachable.

### What did you see happen?

```
Server.IdleTimeout=0s Transport.HTTP2.SendPingTimeout=0s: server conn reachable for 100ms, client conn for 0s
Server.IdleTimeout=3s Transport.HTTP2.SendPingTimeout=0s: server conn reachable for 3.1s, client conn for 0s
Server.IdleTimeout=0s Transport.HTTP2.SendPingTimeout=3s: server conn reachable for 100ms, client conn for 3s
```

**Server.** A connection that closes while a stream is open stays reachable for exactly `Server.IdleTimeout`, with no goroutine left: the `*serverConn`, its framer and buffers, the `*http.Server` and its `Handler`, and — through `wroteFrameCh` / `wantWriteFrameCh` — the slice a handler had passed to `Write` when the loop ended. With a five-minute `IdleTimeout`, every client that vanishes under an open stream costs its connection's memory for five more minutes.

In `net/http/internal/http2/server.go`, `(*serverConn).serve` defers `sc.closeAllStreamsOnConnClose()` and, later, `sc.idleTimer.Stop()`. Deferred calls run last-in first-out, so the timer is stopped first; `closeAllStreamsOnConnClose` then calls `closeStream` for each stream still open, and `closeStream`, when `len(sc.streams) == 0`, does `sc.idleTimer.Reset(idleTimeout)`. Nothing stops the timer again; it fires `IdleTimeout` later into a closed `doneServing`. On master the same order is in `teardown()`.

A stream that the client resets while the connection lives on is released at once, as is anything over HTTP/1.1; `IdleTimeout: 0` avoids it.

**Client.** `(*clientConnReadLoop).run` in `transport.go` arms `t = time.AfterFunc(readIdleTimeout, cc.healthCheck)`, resets it after every `ReadFrame` (the failing one included) and returns without stopping it. Every connection that closes keeps its `*ClientConn` (and the `Transport` behind it) reachable for `SendPingTimeout`, after which `healthCheck` runs on the closed connection. (`forgetStreamID` has the server's shape too: with `IdleConnTimeout` set it resets `cc.idleTimer` on a connection that has already closed.)

### What did you expect to see?

A closed connection to be collectable as soon as its goroutines are gone, whatever `IdleTimeout` and `SendPingTimeout` are.

Two small changes do it, and with them (applied with `go test -overlay`) every case releases at once:

```diff
--- a/src/net/http/internal/http2/server.go
+++ b/src/net/http/internal/http2/server.go
@@ func (sc *serverConn) closeAllStreamsOnConnClose() {
 	for _, st := range sc.streams {
 		sc.closeStream(st, errClientDisconnected)
 	}
+	if sc.idleTimer != nil {
+		sc.idleTimer.Stop()
+	}
 }
--- a/src/net/http/internal/http2/transport.go
+++ b/src/net/http/internal/http2/transport.go
@@ func (rl *clientConnReadLoop) run() error {
 	if readIdleTimeout != 0 {
 		t = time.AfterFunc(readIdleTimeout, cc.healthCheck)
+		defer t.Stop()
 	}
```

Reproducer (`repro_test.go` in an empty module with `go 1.27.0`; `go test -v -run . .`):

```go
// Reproducer: standard library only.
//
//	go test -v -run . .
//
// Server: a connection that closes while a stream is still open keeps its *serverConn — and the
// http.Server, its Handler and the net.Conn with it — reachable for Server.IdleTimeout.
// Client: every connection that closes keeps its *ClientConn reachable for HTTP2.SendPingTimeout.
package h2idlerepro

import (
	"context"
	"net"
	"net/http"
	"runtime"
	"sync/atomic"
	"testing"
	"time"
)

type tracked struct {
	net.Conn
	_ [64]byte
}

type listener struct {
	net.Listener
	gone *atomic.Bool
}

func (l listener) Accept() (net.Conn, error) {
	c, err := l.Listener.Accept()
	if err != nil {
		return nil, err
	}
	tc := &tracked{Conn: c}
	runtime.AddCleanup(tc, func(g *atomic.Bool) { g.Store(true) }, l.gone)
	return tc, nil
}

// heldFor forces collections until gone is set and reports how long that took.
func heldFor(gone *atomic.Bool, limit time.Duration) time.Duration {
	start := time.Now()
	for !gone.Load() && time.Since(start) < limit {
		runtime.GC()
		time.Sleep(50 * time.Millisecond)
	}
	return time.Since(start).Round(100 * time.Millisecond)
}

// run opens one streaming request and cuts the client's socket under it. It reports how long the
// server's and the client's connection objects stayed reachable afterwards; the server keeps serving.
func run(t *testing.T, serverIdle, clientPing time.Duration) (server, client time.Duration) {
	var serverGone, clientGone atomic.Bool
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	started, returned := make(chan struct{}), make(chan struct{})
	srv := &http.Server{
		IdleTimeout: serverIdle,
		Protocols:   new(http.Protocols),
		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(200)
			http.NewResponseController(w).Flush()
			close(started)
			<-r.Context().Done()
			close(returned)
		}),
	}
	srv.Protocols.SetUnencryptedHTTP2(true)
	go srv.Serve(listener{ln, &serverGone})
	defer srv.Close()

	var sock net.Conn
	tr := &http.Transport{
		Protocols: new(http.Protocols),
		HTTP2:     &http.HTTP2Config{SendPingTimeout: clientPing},
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			c, err := (&net.Dialer{}).DialContext(ctx, network, addr)
			if err != nil {
				return nil, err
			}
			sock = c
			tc := &tracked{Conn: c}
			runtime.AddCleanup(tc, func(g *atomic.Bool) { g.Store(true) }, &clientGone)
			return tc, nil
		},
	}
	tr.Protocols.SetUnencryptedHTTP2(true)
	req, _ := http.NewRequest("GET", "http://"+ln.Addr().String(), nil)
	res, err := tr.RoundTrip(req)
	if err != nil {
		t.Fatal(err)
	}
	<-started
	sock.Close() // the peer vanishes: no RST_STREAM, the stream is open when the connection ends
	<-returned
	res.Body.Close()
	tr.CloseIdleConnections()
	return heldFor(&serverGone, serverIdle+5*time.Second), heldFor(&clientGone, clientPing+5*time.Second)
}

func TestHeld(t *testing.T) {
	for _, c := range []struct{ serverIdle, clientPing time.Duration }{{0, 0}, {3 * time.Second, 0}, {0, 3 * time.Second}} {
		server, client := run(t, c.serverIdle, c.clientPing)
		t.Logf("Server.IdleTimeout=%v Transport.HTTP2.SendPingTimeout=%v: server conn reachable for %v, client conn for %v", c.serverIdle, c.clientPing, server, client)
	}
}
```

