// dupKeys builds tags whose attribute keys all have the same length and
// differ only in their last two bytes, which makes every key comparison read
// the whole key. Each tag has `distinct` keys followed by `dups` upper-case
// duplicates of the last one, so z.attr stops growing and every duplicate is
// checked against all saved keys.
func dupKeys(keyLen, distinct, dups int) []byte {
	var b strings.Builder
	prefix := strings.Repeat("k", keyLen-2)
	key := func(i int) string { return prefix + string(rune('a'+i/26)) + string(rune('a'+i%26)) }
	for t := 0; t < 20; t++ {
		b.WriteString("<div")
		for i := 0; i < distinct; i++ {
			b.WriteString(" " + key(i) + "=1")
		}
		last := " " + strings.ToUpper(key(distinct-1)) + "=1"
		for i := 0; i < dups; i++ {
			b.WriteString(last)
		}
		b.WriteString(">")
	}
	return []byte(b.String())
}

func BenchmarkAdversarial(b *testing.B) {
	for _, distinct := range []int{7, 31} {
		for _, keyLen := range []int{16, 64, 4096} {
			in := dupKeys(keyLen, distinct, 64*1024/keyLen)
			b.Run(fmt.Sprintf("distinct=%d/keyLen=%d", distinct, keyLen), func(b *testing.B) {
