package main

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"errors"
	"fmt"
	"math/big"
	"time"
)

type side struct {
	conn          *tls.QUICConn
	done          bool
	rejectedEarly bool
}

func run(cli, srv *side, ticketOpts tls.QUICSessionTicketOptions) error {
	for _, s := range []*side{cli, srv} {
		s.conn.SetTransportParameters(nil)
		if err := s.conn.Start(context.Background()); err != nil {
			return err
		}
	}
	a, b := cli, srv
	idle := 0
	for {
		e := a.conn.NextEvent()
		switch e.Kind {
		case tls.QUICNoEvent:
			idle++
			if idle == 2 {
				if !a.done || !b.done {
					return errors.New("handshake incomplete")
				}
				return nil
			}
			a, b = b, a
			continue
		case tls.QUICWriteData:
			if err := b.conn.HandleData(e.Level, e.Data); err != nil {
				return err
			}
		case tls.QUICHandshakeDone:
			a.done = true
			if a == srv {
				if err := srv.conn.SendSessionTicket(ticketOpts); err != nil {
					return err
				}
			}
		case tls.QUICRejectedEarlyData:
			a.rejectedEarly = true
		}
		idle = 0
	}
}

func selfSigned() tls.Certificate {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		panic(err)
	}
	tmpl := &x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: "example.com"},
		DNSNames:     []string{"example.com"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		panic(err)
	}
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
}

func main() {
	cert := selfSigned()
	for _, earlyData := range []bool{false, true} {
		fmt.Printf("server tickets allow 0-RTT: %v\n", earlyData)
		serverConfig := &tls.Config{
			MinVersion:       tls.VersionTLS13,
			Certificates:     []tls.Certificate{cert},
			NextProtos:       []string{"h3"},
			CurvePreferences: []tls.CurveID{tls.CurveP384},
		}
		clientConfig := &tls.Config{
			MinVersion:         tls.VersionTLS13,
			ServerName:         "example.com",
			InsecureSkipVerify: true,
			NextProtos:         []string{"h3"},
			ClientSessionCache: tls.NewLRUClientSessionCache(1),
		}
		for i := 1; i <= 2; i++ {
			cli := &side{conn: tls.QUICClient(&tls.QUICConfig{TLSConfig: clientConfig})}
			srv := &side{conn: tls.QUICServer(&tls.QUICConfig{TLSConfig: serverConfig})}
			err := run(cli, srv, tls.QUICSessionTicketOptions{EarlyData: earlyData})
			if err != nil {
				var alert tls.AlertError
				if errors.As(err, &alert) {
					fmt.Printf("  connection %d: FAIL: %v (alert %d)\n", i, err, uint8(alert))
				} else {
					fmt.Printf("  connection %d: FAIL: %v\n", i, err)
				}
			} else {
				fmt.Printf("  connection %d: ok, resumed=%v, 0-RTT rejected=%v\n", i, cli.conn.ConnectionState().DidResume, cli.rejectedEarly)
			}
			cli.conn.Close()
			srv.conn.Close()
		}
	}
}
